def initialize_grid(N, k):
    grid = np.zeros((N, N), dtype=int)
    cells = [(r, c) for r in range(N) for c in range(N)]
    if k > N * N:
        raise ValueError("k too large")

    infected_indices = random.sample(cells, k)
