def apply_rules(grid):
    N = grid.shape[0]
    new_grid = grid.copy()

    # Identify all 2x2 squares
    for r in range(N - 1):
        for c in range(N - 1):
            S = [
                grid[r, c], grid[r+1, c],
                grid[r, c+1], grid[r+1, c+1]
            ]
            sum_S = sum(S)

            # Rule 1: Growth (3/4 infected)
            if sum_S == 3:
                # Find the sterile section and infect it
                for i in range(4):
                    if S[i] == 0:
                        # Map index i back to (r, c) coordinates
                        dr = [0, 1, 0, 1][i]
